try:
    date
except NameError:
    date = None
try:
    israel
except NameError:
    israel = None
try:
    hebrew
except NameError:
    hebrew = None
try:
    prefix_day
except NameError:
    prefix_day = None

if not isinstance(date, str):
    raise ValueError("date must be a string in YYYY-MM-DD format")
date = date.strip()
parts = date.split("-")
if len(parts) != 3 or not (len(parts[0]) == 4 and len(parts[1]) == 2 and len(parts[2]) == 2):
    raise ValueError("date must be in YYYY-MM-DD format")
try:
    year, month, day = (int(part) for part in parts)
except ValueError as exc:
    raise ValueError("date must contain integer year, month, and day") from exc

if israel is None:
    israel = False
if hebrew is None:
    hebrew = False
if prefix_day is None:
    prefix_day = False
if not isinstance(israel, bool):
    raise ValueError("israel must be a boolean")
if not isinstance(hebrew, bool):
    raise ValueError("hebrew must be a boolean")
if not isinstance(prefix_day, bool):
    raise ValueError("prefix_day must be a boolean")

try:
    date_obj = GregorianDate(year, month, day)
except Exception as exc:
    raise ValueError(f"invalid Gregorian date: {date}") from exc

fast_name = fast_day(date_obj, hebrew=hebrew)
festival_name = festival(date_obj, israel=israel, hebrew=hebrew, include_working_days=True, prefix_day=prefix_day)
holiday_name = holiday(date_obj, israel=israel, hebrew=hebrew, prefix_day=prefix_day)

if fast_name is not None:
    kind = "fast_day"
elif festival_name is not None:
    kind = "festival"
else:
    kind = None

return {
    "date": date,
    "holiday": holiday_name,
    "is_holiday": holiday_name is not None,
    "kind": kind,
    "fast_day": fast_name,
    "is_fast_day": fast_name is not None,
    "festival": festival_name,
    "is_festival": festival_name is not None,
}

